'use strict';

const debug = require('debug')('dsr:protocol:ConnectionSerialization');
const ByteBuffer = require('byte');
const javaio = require('java.io');

const HEADER_ONEWAY = 1; // 单向通信
const HEADER_TWOWAY = 2; // 双向通信
const HEADER_REQUEST = 0; // 请求
const HEADER_RESPONSE = 1; // 响应
const PROCOCOL_VERSION = 0x0d; // (byte) 13;
const JAVA_SERIALIZE = 2; // Java序列化 ;
const PROTOCOL_HEADER_LENGTH = 14;


const ConnectionSerialization = Object.create(null);

const HEADERS = {
  'com.taobao.remoting.impl.ConnectionHeartBeat': {
    direction: HEADER_ONEWAY,
    type: HEADER_REQUEST,
  },
  'com.taobao.remoting.impl.ConnectionRequest': {
    direction: HEADER_TWOWAY,
    type: HEADER_REQUEST,
  },
  'com.taobao.remoting.impl.ConnectionResponse': {
    direction: 0,
    type: HEADER_RESPONSE,
  },
};

const HEADER_LENGTH = ConnectionSerialization.HEADER_LENGTH = 14;

ConnectionSerialization.serialize = function(connObject) {
  // 序列化通信层对象
  const connObjBuf = javaio.OutputObjectStream.writeObject(connObject);
  let size = HEADER_LENGTH + connObjBuf.length;
  // 序列化业务层对象
  const appObject = connObject.$.appObject;
  let appObjBuf;
  let appClassNameBuf;
  if (appObject) {
    const appClassName = appObject.$class.name;
    appObjBuf = javaio.OutputObjectStream.writeObject(appObject);
    appClassNameBuf = new Buffer(appClassName);
    size += appClassNameBuf.length + appObjBuf.length;
  }

  const bytes = ByteBuffer.allocate(size);

  const header = HEADERS[connObject.$class.name];
  bytes.put(PROCOCOL_VERSION);
  bytes.put(header.type);
  bytes.put(JAVA_SERIALIZE);
  bytes.put(header.direction);
  bytes.put(0);
  bytes.putInt32(connObjBuf.length);

  if (appObject) {
    bytes.put(appClassNameBuf.length);
    bytes.putInt32(appObjBuf.length);
    bytes.put(connObjBuf);
    bytes.put(appClassNameBuf);
    bytes.put(appObjBuf);
  } else {
    bytes.put(0);
    bytes.putInt32(0);
    bytes.put(connObjBuf);
  }
  return bytes.copy();
};

ConnectionSerialization.deserializeHeader = function(bytes) {
  if (bytes.length < PROTOCOL_HEADER_LENGTH) {
    // size must bigger than PROTOCOL_HEADER_LENGTH
    throw new TypeError('decode buffer size < PROTOCOL_HEADER_LENGTH, current: ' +
      bytes.length + ', expected >= ' + PROTOCOL_HEADER_LENGTH);
  }

  if (Buffer.isBuffer(bytes)) {
    bytes = ByteBuffer.wrap(bytes);
  }

  // parse head
  const version = bytes.get();
  const headerType = bytes.get();
  const serializeProtocol = bytes.get();
  if (version !== 0xD || (headerType !== 0x0 && headerType !== 0x1)) {
    // head error
    debug('decode buffer head version or type error');
    throw new TypeError('decode buffer head version or type error, version: ' +
      version + ', type: ' + headerType);
  }

  const direction = bytes.get(); // 0,1,2
  bytes.skip(1);

  const connLen = bytes.getInt32();
  const appClassnameLen = bytes.get();
  const appLen = bytes.getInt32();

  return {
    protocolVersion: version,
    headerType,
    serializeProtocol,
    direction,
    connLen,
    appClassNameLen: appClassnameLen,
    appLen,
  };
};

ConnectionSerialization.deserializeBody = function(header, bytes, withType) {
  if (Buffer.isBuffer(bytes)) {
    bytes = ByteBuffer.wrap(bytes);
  }

  const connLen = header.connLen;
  const appClassnameLen = header.appClassNameLen;
  const appLen = header.appLen;
  const headerType = header.headerType;
  const protocolVersion = header.protocolVersion;
  const serializeProtocol = header.serializeProtocol;

  if (PROCOCOL_VERSION !== protocolVersion) {
    throw new Error('报文版本头字段不正确.');
  } else if (JAVA_SERIALIZE !== serializeProtocol) {
    throw new Error('报文序列化协议头字段不正确.');
  }

  // 反序列化通信层对象
  const connObject = javaio.InputObjectStream.readObject(bytes.read(connLen), withType);

  // 反序列化业务请求
  let appClassName = null;
  if (appClassnameLen > 0) {
    appClassName = bytes.read(appClassnameLen).toString();
  }

  let appRequest = null;
  if (appLen > 0) {
    debug('deserializing %s', appClassName);
    appRequest = javaio.InputObjectStream.readObject(bytes.read(appLen), withType);
  }

  // 组装通信层对象
  if (withType) {
    connObject.$.appClassName = appClassName;
    connObject.$.appObject = appRequest;
    connObject.$.isResponse = headerType === 1;
    connObject.$.isRequest = headerType === 0;
    connObject.$.requestFlag = headerType;
  } else {
    connObject.appClassName = appClassName;
    connObject.appObject = appRequest;
    connObject.isResponse = headerType === 1;
    connObject.isRequest = headerType === 0;
    connObject.requestFlag = headerType;
  }
  return connObject;
};

ConnectionSerialization.deserialize = function(bytes, withType) {
  bytes = ByteBuffer.wrap(bytes);
  const header = exports.deserializeHeader(bytes);
  return ConnectionSerialization.deserializeBody(header, bytes, withType);
};

module.exports = ConnectionSerialization;
